@testitem "slic: builtin implementations explain themselves in emitted Stan" tags=[:slic, :regression] setup=[StanBlocksImports] begin
    weighted_model = @slic (; y = [0.2, -0.1], w = [0.5, 2.0]) begin
        mu ~ normal(0.0, 1.0)
        y ~ weighted(normal, w, mu, 1.0)
        tail = normal_lcdf_stable(mu, 0.0, 1.0)
    end
    code = stan_code(weighted_model)
    # Comments precede definitions, including HOF specializations and the
    # sized RNG overloads generated by an @eval loop in builtin.jl.
    for (comment, signature) in (
        ("Sum the elementwise products of observation weights and base log probabilities.",
         r"real weighted_normal_lpdf\("),
        ("Return the elementwise products of observation weights and base log probabilities.",
         r"vector weighted_normal_lpdfs\("),
        ("Compute log P(Y <= x) for a normal distribution, preserving small tail probabilities and handling infinite bounds directly.",
         r"real normal_lcdf_stable\("),
        ("Draw independent values of the requested size, broadcasting scalar parameters and preserving the requested container type.",
         r"vector normal_vector_rng\("),
    )
        lines = split(code, '\n')
        positions = findall(line -> strip(line) == "// " * comment, lines)
        @test !isempty(positions)
        @test any(at -> occursin(signature, strip(lines[at + 1])), positions)
    end

    # The words explain the operation, including a discrete truncation's
    # inclusive bound and the distinction between censoring and conditioning.
    truncated_model = @slic (; y = 2) begin
        rate ~ exponential(1.0)
        y ~ truncated(poisson(rate); lower = 1)
    end
    censored_model = @slic (; y = 0.0) begin
        mu ~ normal(0.0, 1.0)
        y ~ censored(normal(mu, 1.0); lower = 0.0)
    end
    @test occursin("minus log P(Y >= lo)", stan_code(truncated_model))
    @test occursin("log P(Y <= lo) at lo", stan_code(censored_model))

    # @juliacompat still emits its callable Julia method when documented.
    @test StanBlocks.stan.ragged_start([2, 5], 2) == 3
end
